"use client";

import { loadFont as loadDisplay } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import type React from "react";
import { type ReactNode, useId } from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type BracketFocusElementId,
  bracketFocusTimeline,
  CORNERS,
} from "./timeline";

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const { fontFamily: mono } = loadMono("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface BracketFocusProps {
  subject?: string;
  tag?: string;
  /** Weight of the subject. */
  fontWeight?: number;
  /** Frames the brackets take to fly in from the frame's edges. */
  fly?: number;
  accent?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the subject. Load it yourself; Geist by default. */
  fontFamily?: string;
  /** Size of the framed subject, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the grid, the subject, single corners, the
   * tag, the focus and the readout, by the ids in `./timeline`. Frames on
   * the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<BracketFocusElementId>;
}

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    rest: "#6E6D73",
    dot: "rgba(255,255,255,0.2)",
    tick: "rgba(255,255,255,0.4)",
    readout: "rgba(243,242,239,0.5)",
    // gradients.sh "beam": #f4f7ff → #8fb4ff → #3d5bff
    hero: ["#F4F7FF", "#C4D5FF", "#8FB4FF", "#5C78FF"],
    grain: 0.055,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    rest: "#A3A19B",
    dot: "rgba(18,18,20,0.2)",
    tick: "rgba(18,18,20,0.4)",
    readout: "rgba(18,18,20,0.5)",
    // gradients.sh "beam", deep end first so it reads on off-white
    hero: ["#1A1660", "#2B32B8", "#3D5BFF", "#6F8FFF"],
    grain: 0.04,
  },
} as const;

function widthEm(text: string) {
  let w = 0;
  for (const ch of text) {
    if (ch === " ") w += 0.26;
    else if (".,:;'!|".includes(ch)) w += 0.27;
    else if (ch >= "0" && ch <= "9") w += 0.6;
    else if ("ijlI".includes(ch)) w += 0.25;
    else if ("ftr".includes(ch)) w += 0.36;
    else if ("mwMW%".includes(ch)) w += 0.84;
    else if (ch >= "A" && ch <= "Z") w += 0.66;
    else w += 0.54;
    w -= 0.035;
  }
  return Math.max(w, 0.6);
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function bracketPath(x: number, y: number, sx: number, sy: number, L: number) {
  return `M ${x} ${y - sy * L} L ${x} ${y} L ${x - sx * L} ${y}`;
}

export function BracketFocus(props: BracketFocusProps) {
  const {
    subject = "1.8s",
    tag = "Render time",
    fontWeight = 500,
    accent = "#3B5BFD",
    background,
    fontFamily = display,
    scale = 1,
    delay = 0,
    grain = true,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const now = useSceneFrame();
  const tAt = (n: number) => Math.max(0, n - delay) * speed;
  const t = tAt(now);
  /** Whether a value in px, as a function of time, moves on this frame. */
  const stirs = (v: (t: number) => number) => {
    const here = v(t);
    return (
      Math.abs(v(tAt(now + 1)) - here) > 1e-3 ||
      Math.abs(here - v(tAt(now - 1))) > 1e-3
    );
  };
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    bracketFocusTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const gridEl = tl.get("grid");
  const subjectEl = tl.get("subject");
  const tagEl = tl.get("tag");
  const focusEl = tl.get("focus");
  const readEl = tl.get("readout");
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];
  const stage = background ?? p.bg;
  const maskId = `m${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const cx = W / 2;
  const cy = H / 2;
  const size = Math.min(272 * u, (0.6 * W) / widthEm(subject));
  const textW = widthEm(subject) * size;
  const capH = 0.74 * size;
  const pad = 46 * u;
  const tight = { hw: textW / 2 + pad * 1.05, hh: capH / 2 + pad * 0.9 };
  const loose = { hw: tight.hw + 46 * u, hh: tight.hh + 36 * u };
  const margin = 0.07 * W;
  const far = { hw: W / 2 - margin, hh: H / 2 - margin };

  const arm = 46 * u;
  const stroke = 3 * u;

  const place = (sx: number, sy: number, fly: number, snap: number) => {
    const hw =
      far.hw + (loose.hw - far.hw) * fly + (tight.hw - loose.hw) * snap;
    const hh =
      far.hh + (loose.hh - far.hh) * fly + (tight.hh - loose.hh) * snap;
    return { x: cx + sx * hw, y: cy + sy * hh };
  };
  const corner = (i: number, at: number) => {
    const { sx, sy } = CORNERS[i];
    const e = tl.get(`corner:${i}`);
    const fly = EASE_IO(interpolate(at, [e.start, e.end], [0, 1], CLAMP));
    const snap = spring({
      frame: at - e.end,
      fps,
      config: { damping: 13, stiffness: 320, mass: 0.55 },
    });
    return place(sx, sy, fly, snap);
  };

  // The tag and the readout ride the snapping corners. They are laid out
  // where the corners settle and the ride is a transform: layout rounds a box
  // and a baseline to whole pixels, so a label eased by `left`/`top` clicks
  // along pixel by pixel. The snap is a spring, so the leftover is dropped,
  // but the transform stays: without it the tag loses its mark and snaps to a
  // whole pixel on the frame it goes.
  const shiftOf = (i: number) => {
    const { sx, sy } = CORNERS[i];
    const live = corner(i, t);
    const rest = place(sx, sy, 1, 1);
    const dx = live.x - rest.x;
    const dy = live.y - rest.y;
    const still = Math.abs(dx) < 1e-3 && Math.abs(dy) < 1e-3;
    const moving = stirs((t) => corner(i, t).x) || stirs((t) => corner(i, t).y);
    return { rest, dx, dy, still, moving };
  };
  // The tag rides the top-left corner, the readout the bottom-right one.
  const tagRide = shiftOf(0);
  const readRide = shiftOf(2);
  const appear = interpolate(t, [gridEl.start, gridEl.end], [0.35, 1], CLAMP);
  const dim = EASE_IO(
    interpolate(t, [focusEl.start, focusEl.end], [0, 1], CLAMP),
  );
  const tagIn = EASE_OUT(
    interpolate(t, [tagEl.start, tagEl.end], [0, 1], CLAMP),
  );
  const tagTextAt = tagEl.start + tagEl.beat("textAt");
  const tagText = EASE_OUT(
    interpolate(t, [tagTextAt, tagTextAt + tagEl.beat("text")], [0, 1], CLAMP),
  );
  const liftAt = focusEl.start + focusEl.beat("liftAt");
  const subjectAt = (t: number) => {
    const subjectIn = EASE_OUT(
      interpolate(t, [subjectEl.start, subjectEl.end], [0.25, 1], CLAMP),
    );
    const lift = EASE_OUT(
      interpolate(t, [liftAt, liftAt + focusEl.beat("lift")], [0, 1], CLAMP),
    );
    const push = EASE_IO(
      interpolate(t, [0, focusEl.start + focusEl.beat("push")], [0, 1], CLAMP),
    );
    return { subjectIn, lift, push };
  };
  const { subjectIn, lift, push } = subjectAt(t);
  // Weighed at the subject's far edge, so both terms are in px.
  const subjectMoving =
    stirs((t) => (1 - subjectAt(t).subjectIn) * 10 * u) ||
    stirs((t) => {
      const q = subjectAt(t);
      return (0.985 + 0.015 * q.lift + 0.012 * q.push) * (textW / 2);
    });

  const tagH = 32 * u;
  const tagFont = 14 * u;
  const tagW = tag.length * 0.6 * tagFont * 1.06 + 26 * u;
  const readAt = (t: number) =>
    EASE_OUT(interpolate(t, [readEl.start, readEl.end], [0, 1], CLAMP));
  const readIn = readAt(t);
  const readMoving = readRide.moving || stirs((t) => (1 - readAt(t)) * 6 * u);
  const boxW = Math.round((tight.hw * 2) / u);
  const boxH = Math.round((tight.hh * 2) / u);
  const drift = interpolate(t, [0, 150], [0, 1], CLAMP);
  const heroGradient = `linear-gradient(${112 + 10 * drift}deg, ${p.hero[0]} ${-8 + 10 * drift}%, ${p.hero[1]} ${30 + 6 * drift}%, ${p.hero[2]} ${62 + 4 * drift}%, ${p.hero[3]} 104%)`;

  const gap = 32 * u;
  const cols = Math.floor((W - 2 * margin) / gap);
  const rows = Math.floor((H - 2 * margin) / gap);
  const ox = (W - cols * gap) / 2;
  const oy = (H - rows * gap) / 2;
  const dots: React.ReactNode[] = [];
  for (let r = 0; r <= rows; r++) {
    for (let c = 0; c <= cols; c++) {
      const x = ox + c * gap;
      const y = oy + r * gap;
      const d = Math.hypot((x - cx) / W, (y - cy) / H);
      const at = gridEl.start + d * gridEl.beat("ripple");
      const wave = interpolate(
        t,
        [at, at + gridEl.beat("wave")],
        [0, 1],
        CLAMP,
      );
      dots.push(
        <circle
          key={`${r}-${c}`}
          cx={x}
          cy={y}
          r={1.4 * u}
          fill={p.dot}
          opacity={wave}
        />,
      );
    }
  }

  const ticks: React.ReactNode[] = [];
  const tickN = 24;
  for (let i = 0; i <= tickN; i++) {
    const x = margin + ((W - 2 * margin) * i) / tickN;
    const long = i % 6 === 0;
    const len = (long ? 12 : 6) * u;
    for (const yEdge of [margin - 22 * u, H - margin + 22 * u]) {
      const dir = yEdge < cy ? 1 : -1;
      ticks.push(
        <line
          key={`${i}-${yEdge}`}
          x1={x}
          x2={x}
          y1={yEdge}
          y2={yEdge + dir * len}
          stroke={p.tick}
          strokeWidth={Math.max(1, u)}
        />,
      );
    }
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            opacity: appear * (1 - 0.6 * dim),
            transform: `scale(${1.02 - 0.02 * push})`,
          }}
        >
          <svg width={W} height={H} style={{ position: "absolute", inset: 0 }}>
            <defs>
              <mask id={maskId}>
                <rect width={W} height={H} fill="white" />
                <rect
                  x={cx - loose.hw}
                  y={cy - loose.hh}
                  width={loose.hw * 2}
                  height={loose.hh * 2}
                  fill="black"
                />
              </mask>
            </defs>
            <g mask={`url(#${maskId})`}>{dots}</g>
            {ticks}
          </svg>
        </AbsoluteFill>

        <AbsoluteFill
          style={{
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              position: "relative",
              fontFamily,
              fontWeight,
              fontSize: size,
              lineHeight: 1,
              letterSpacing: "-0.035em",
              whiteSpace: "nowrap",
              fontVariantNumeric: "tabular-nums",
              opacity: subjectIn,
              transform: `translate(${-0.02 * size}px, ${(1 - subjectIn) * 10 * u}px) scale(${0.985 + 0.015 * lift + 0.012 * push})${glide(subjectMoving)}`,
            }}
          >
            <span style={{ color: p.rest, opacity: 1 - lift }}>{subject}</span>
            <span
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                backgroundImage: heroGradient,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                color: "transparent",
                opacity: lift,
              }}
            >
              {subject}
            </span>
          </div>
        </AbsoluteFill>

        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0, opacity: appear }}
        >
          {CORNERS.map(({ sx, sy }, i) =>
            [2.4, 1.2, 0].map((lag) => {
              const c = corner(i, t - lag);
              const now = corner(i, t);
              const moved = Math.hypot(c.x - now.x, c.y - now.y);
              const o = lag === 0 ? 1 : lag > 2 ? 0.12 : 0.26;
              if (lag > 0 && moved < 2 * u) return null;
              return (
                <path
                  key={`${sx}${sy}${lag}`}
                  d={bracketPath(c.x, c.y, sx, sy, arm)}
                  fill="none"
                  stroke={accent}
                  strokeWidth={stroke}
                  strokeLinecap="square"
                  opacity={o}
                />
              );
            }),
          )}
        </svg>

        <div
          style={{
            position: "absolute",
            left: tagRide.rest.x - stroke / 2,
            top: tagRide.rest.y - stroke / 2 - tagH,
            transform: tagRide.still
              ? `translate(0px, 0px)${glide(tagRide.moving)}`
              : `translate(${tagRide.dx}px, ${tagRide.dy}px)${glide(tagRide.moving)}`,
            height: tagH,
            width: tagW,
            background: accent,
            borderRadius: `${4 * u}px ${4 * u}px ${4 * u}px 0`,
            clipPath: `inset(${(1 - tagIn) * 100}% ${(1 - tagIn) * 100}% 0 0)`,
            display: "flex",
            alignItems: "center",
            paddingLeft: 12 * u,
            boxSizing: "border-box",
          }}
        >
          <span
            style={{
              fontFamily: mono,
              fontWeight: 500,
              fontSize: tagFont,
              letterSpacing: "0.06em",
              textTransform: "uppercase",
              color: "#FFFFFF",
              whiteSpace: "nowrap",
              opacity: tagText,
              transform: `translateX(${(1 - tagText) * -6 * u}px)`,
            }}
          >
            {tag}
          </span>
        </div>

        <div
          style={{
            position: "absolute",
            right: W - readRide.rest.x - stroke / 2,
            top: readRide.rest.y + 14 * u,
            fontFamily: mono,
            fontWeight: 400,
            fontSize: 13 * u,
            letterSpacing: "0.04em",
            fontVariantNumeric: "tabular-nums",
            color: p.readout,
            whiteSpace: "pre",
            opacity: readIn,
            transform: readRide.still
              ? `translateY(${(1 - readIn) * 6 * u}px)${glide(readMoving)}`
              : `translate(${readRide.dx}px, ${readRide.dy + (1 - readIn) * 6 * u}px)${glide(readMoving)}`,
          }}
        >
          {`W ${boxW}  ×  H ${boxH}`}
        </div>
      </ScaleLayer>

      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The dot grid rippling out and the subject fading up, the four corner
// brackets flying in from the frame's edges and snapping tight round it,
// the tag and the size readout riding their corners, and the focus: the
// grid dims while the subject lights up in the gradient. Frames on the
// 30 fps scene timeline, after `delay` and `speed`. The ids are public: a
// saved `timing` prop refers to them.

export type BracketFocusElementId =
  | "grid"
  | "subject"
  | `corner:${number}`
  | "tag"
  | "focus"
  | "readout";

export interface BracketFocusTimingProps {
  fly?: number;
}

export const CORNERS = [
  { sx: -1, sy: -1, delay: 0 },
  { sx: 1, sy: -1, delay: 2 },
  { sx: 1, sy: 1, delay: 3 },
  { sx: -1, sy: 1, delay: 5 },
] as const;

const CORNER_LABELS = ["top left", "top right", "bottom right", "bottom left"];
const FLY_AT = 10;
export const FLY_LEN = 22;
/** The grid fades up over `GRID`; a dot lights `RIPPLE` per unit of distance, over `WAVE`. */
const GRID = 8;
const RIPPLE = 18;
const WAVE = 10;
const SUBJECT = 16;
/** The tag opens `TAG_AT` after the snap; its text slides in from `textAt` over `text`. */
const TAG_AT = 6;
const TAG = 14;
const TAG_TEXT_AT = 4;
const TAG_TEXT = 12;
/** The readout fades in `READ_AT` after the tag. */
const READ_AT = 8;
const READ = 14;
/** The focus dims the grid from `DIM_AT` after the snap; the subject lights from `liftAt` over `lift`. */
const DIM_AT = 8;
const DIM = 22;
const LIFT_AT = -2;
const LIFT = 20;
/** The slow push in runs from the start until `push` into the focus. */
const PUSH = 50;

// `corner:<i>` flies in over its length and snaps at its end (top left, top
// right, bottom right, bottom left); the corners form a chain. `tag` and
// `focus` follow the first corner's snap, `readout` follows the tag.
export const bracketFocusTimeline = defineTimeline<
  BracketFocusElementId,
  BracketFocusTimingProps
>(({ fly = FLY_LEN }) => {
  const snapAt = FLY_AT + fly;
  const tagAt = snapAt + TAG_AT;
  const dimAt = snapAt + DIM_AT;
  const elements: TimelineElement<BracketFocusElementId>[] = [
    {
      id: "grid",
      lane: "Grid",
      label: "grid",
      start: 0,
      length: GRID,
      beats: { ripple: RIPPLE, wave: WAVE },
    },
    {
      id: "subject",
      lane: "Subject",
      label: "subject",
      start: 0,
      length: SUBJECT,
    },
    ...CORNERS.map(
      (c, i): TimelineElement<BracketFocusElementId> => ({
        id: `corner:${i}`,
        lane: "Brackets",
        label: CORNER_LABELS[i],
        start: FLY_AT + c.delay,
        length: fly,
        follows: i > 0 ? `corner:${i - 1}` : undefined,
      }),
    ),
    {
      id: "tag",
      lane: "Labels",
      label: "tag",
      start: tagAt,
      length: TAG,
      follows: "corner:0",
      beats: { textAt: TAG_TEXT_AT, text: TAG_TEXT },
    },
    {
      id: "focus",
      lane: "Subject",
      label: "focus",
      start: dimAt,
      length: DIM,
      follows: "corner:0",
      beats: { liftAt: LIFT_AT, lift: LIFT, push: PUSH },
    },
    {
      id: "readout",
      lane: "Labels",
      label: "readout",
      start: tagAt + READ_AT,
      length: READ,
      follows: "tag",
    },
  ];
  return elements;
});
